<?php $this->assign('title', 'Weekly report'); $total = array_sum(array_map(fn($order) => (int)$order->total_cents, $orders)); ?>
<section class="page-heading"><h1>Weekly report</h1><p>Current billing ledger.</p></section>
<section class="items-card"><p><strong>Total billed: $<?= number_format($total/100,2) ?></strong> <?= $this->Html->link('Download CSV', '/admin/weekly-report.csv', ['class'=>'button-primary']) ?></p><table><tr><th>Barrister</th><th>Submitted</th><th>Item type</th><th>Quantity</th><th>Cost</th></tr><?php foreach ($orders as $order): ?><?php foreach ($itemsByOrder[(int)$order->id] ?? [] as $item): ?><tr><td><?= h($order->barrister_name) ?></td><td><?= h($order->submitted_at?->format('d M Y')) ?></td><td><?= h($item->item_name) ?></td><td><?= (int)$item->quantity ?></td><td>$<?= number_format($item->line_total_cents/100,2) ?></td></tr><?php endforeach; ?><?php endforeach; ?></table></section>
